INSERT INTO `diagnostic_nodes` VALUES (7,2,NULL,'Do you see any leaks around the faucet','','QUESTION',0,'2026-01-21 08:45:08'),(8,2,7,'Yes, There is a small pool of water around the faucet','Yes','QUESTION',1,'2026-01-21 08:45:45'),(9,2,7,'Yes, There is a considerable amount of water leaking from the faucet','Yes','QUESTION',2,'2026-01-21 08:46:31'),(10,2,7,'No, The faucet is not leaking, likely just left over water.','No','RESULT',3,'2026-01-21 08:47:18'),(11,2,8,'Is the leaking coming from the base or the sprout?','Yes','QUESTION',1,'2026-01-21 08:48:45'),(12,2,9,'Is the leak coming from the base or the sprout?','Yes','QUESTION',1,'2026-01-21 08:49:07'),(13,2,11,'Likely a lose a washer, please tighten the washer','Base','RESULT',1,'2026-01-21 08:50:01'),(28,5,NULL,'3423423424324','','QUESTION',0,'2026-01-23 12:43:22'),(29,5,28,'3242342','234234','QUESTION',1,'2026-01-23 12:43:28'),(30,5,28,'234234234','242424','QUESTION',2,'2026-01-23 12:43:31'),(31,5,29,'23423424','2424242','QUESTION',1,'2026-01-23 12:43:35'),(32,5,29,'234242344','234242','QUESTION',2,'2026-01-23 12:43:38'),(33,5,30,'4234242','234234324','QUESTION',1,'2026-01-23 12:43:42'),(34,5,30,'4234234242','2342432','QUESTION',2,'2026-01-23 12:43:46'),(35,5,31,'4234242','2342342','RESULT',1,'2026-01-23 12:43:52'),(36,5,32,'4242342','2432342','RESULT',1,'2026-01-23 12:43:57'),(37,5,33,'42342342','234234','QUESTION',1,'2026-01-23 12:44:10'),(58,10,NULL,'Is there chipping off the paint?','','QUESTION',0,'2026-01-30 04:31:17'),(59,10,58,'Does the chipped off paint feel crusty?','Yes','QUESTION',1,'2026-01-30 04:31:59'),(60,10,59,'The paint is too old.','Yes','RESULT',1,'2026-01-30 04:32:20'),(68,10,58,'Are there Bubbles in the paint?','No','QUESTION',2,'2026-04-12 06:35:27'),(69,12,NULL,'Does the machine turn on?','','QUESTION',0,'2026-04-17 13:10:22'),(70,12,69,'Diagnosis: Power supply issue\nSolution: Check plug, socket, fuse, or circuit breaker','No','RESULT',1,'2026-04-17 13:10:48'),(71,12,69,'Is the door/lid properly closed?','Yes','QUESTION',2,'2026-04-17 13:11:14'),(72,12,71,'Diagnosis: Safety lock preventing spin\nSolution: Close lid securely','No','RESULT',1,'2026-04-17 13:11:32'),(73,12,71,'Is the load uneven or too heavy?','Yes','QUESTION',2,'2026-04-17 13:11:48'),(74,12,73,'Diagnosis: Imbalanced load\nSolution: Redistribute clothes evenly','Yes','RESULT',1,'2026-04-17 13:12:22'),(75,12,73,'Is water draining properly?','No','QUESTION',2,'2026-04-17 13:13:03'),(76,12,75,'Diagnosis: Blocked drain pump/filter\nSolution: Clean filter or check hose blockage','No','RESULT',1,'2026-04-17 13:13:22'),(77,12,75,'Do you hear the motor running?','Yes','QUESTION',2,'2026-04-17 13:14:07'),(78,12,77,'Diagnosis: Blocked drain pump/filter\nSolution: Clean filter or check hose blockage','No','RESULT',1,'2026-04-17 13:14:23'),(79,12,77,'Is the drum spinning slowly or not at all?','Yes','QUESTION',2,'2026-04-17 13:15:00'),(80,12,79,'Diagnosis: Worn or broken belt\nSolution: Replace belt','Yes','RESULT',1,'2026-04-17 13:15:29'),(81,12,79,'Diagnosis: Control board or internal fault\nSolution: Technician inspection required','No','RESULT',2,'2026-04-17 13:15:53');
